func NewPaginationValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (PaginationValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing PaginationValue Attribute Value",
				"While creating a PaginationValue value, a missing attribute value was detected. "+
					"A PaginationValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("PaginationValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid PaginationValue Attribute Type",
				"While creating a PaginationValue value, an invalid attribute value was detected. "+
					"A PaginationValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("PaginationValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("PaginationValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra PaginationValue Attribute Value",
				"While creating a PaginationValue value, an extra attribute value was detected. "+
					"A PaginationValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra PaginationValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewPaginationValueUnknown(), diags
	}

	augmentedAttribute, ok := attributes["augmented"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`augmented is missing from object`)

		return NewPaginationValueUnknown(), diags
	}

	augmentedVal, ok := augmentedAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`augmented expected to be basetypes.BoolValue, was: %T`, augmentedAttribute))
	}

	countAttribute, ok := attributes["count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`count is missing from object`)

		return NewPaginationValueUnknown(), diags
	}

	countVal, ok := countAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`count expected to be basetypes.Int64Value, was: %T`, countAttribute))
	}

	pageAttribute, ok := attributes["page"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`page is missing from object`)

		return NewPaginationValueUnknown(), diags
	}

	pageVal, ok := pageAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`page expected to be basetypes.Int64Value, was: %T`, pageAttribute))
	}

	sortMethodAttribute, ok := attributes["sort_method"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`sort_method is missing from object`)

		return NewPaginationValueUnknown(), diags
	}

	sortMethodVal, ok := sortMethodAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`sort_method expected to be basetypes.StringValue, was: %T`, sortMethodAttribute))
	}

	sortOrderAttribute, ok := attributes["sort_order"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`sort_order is missing from object`)

		return NewPaginationValueUnknown(), diags
	}

	sortOrderVal, ok := sortOrderAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`sort_order expected to be basetypes.StringValue, was: %T`, sortOrderAttribute))
	}

	if diags.HasError() {
		return NewPaginationValueUnknown(), diags
	}

	return PaginationValue{
		Augmented:  augmentedVal,
		Count:      countVal,
		Page:       pageVal,
		SortMethod: sortMethodVal,
		SortOrder:  sortOrderVal,
		state:      attr.ValueStateKnown,
	}, diags
}

func NewPaginationValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) PaginationValue {
	object, diags := NewPaginationValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewPaginationValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t PaginationType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewPaginationValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewPaginationValueUnknown(), nil
	}

	if in.IsNull() {
		return NewPaginationValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewPaginationValueMust(PaginationValue{}.AttributeTypes(ctx), attributes), nil
}

func (t PaginationType) ValueType(ctx context.Context) attr.Value {
	return PaginationValue{}
}

type PaginationValue struct {
	Augmented  basetypes.BoolValue   `tfsdk:"augmented"`
	Count      basetypes.Int64Value  `tfsdk:"count"`
	Page       basetypes.Int64Value  `tfsdk:"page"`
	SortMethod basetypes.StringValue `tfsdk:"sort_method"`
	SortOrder  basetypes.StringValue `tfsdk:"sort_order"`
	state      attr.ValueState
}

func (v PaginationValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 5)

	var val tftypes.Value
	var err error

	attrTypes["augmented"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["count"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["page"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["sort_method"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["sort_order"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 5)

		val, err = v.Augmented.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["augmented"] = val

		val, err = v.Count.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["count"] = val

		val, err = v.Page.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["page"] = val

		val, err = v.SortMethod.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["sort_method"] = val

		val, err = v.SortOrder.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["sort_order"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

